    },
    {
     "name": "ordEstado",
     "type": "text(fixed,1,iso8859-1)",
     "column": "ord_estado",
     "legacy": "ord_estado"
    },
    {
     "name": "ordFechaPago",
     "type": "timestamp(local)",
     "column": "ord_fecha_pago",
     "legacy": "ord_fecha_pago"
