       "name": "cuenta",
       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "@i_cuenta"
      },
      {
       "name": "tipoCuenta",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "@i_tipo"
      },
      {
       "name": "valor",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "@i_valor"
      },
      {
       "name": "referencia",
       "type": "text(var,40,iso8859-1)",
       "column": null,
       "legacy": "@i_referencia"
      }
     ],
     "returns": "int",
     "legacy_output": "@o_secuencial"
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "PayOrder",
   "description": "Validates the account type, the order and the funds, computes the tariff, commission and total, debits the account (and the commission separately when applicable), marks the order as paid and commits atomically.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005",
    "RULE-006",
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013"
   ],
   "inputs": [
    {
     "name": "orden",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_orden"
    },
    {
     "name": "empresa",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_empresa"
    },
    {
     "name": "servicio",
     "type": "text(var,10,iso8859-1)",
     "column": null,
     "legacy": "@i_servicio"
    },
    {
     "name": "tipoCuenta",
     "type": "text(fixed,3,iso8859-1)",
