            @Override
            public int markPaid(Integer orden, Integer empresa, LocalDateTime fechaPago, BigDecimal comision) {
                calls.add("markPaid");
                marks.add(new MarkPaidCall(orden, empresa, fechaPago, comision));
                return markPaidResult;
            }
        };
        CompanyTariffRepository tariffs = (empresa, servicio) -> {
            calls.add("tariff.find(" + empresa + "," + servicio + ")");
            return companyTariff;
        };
        ServiceRepository services = servicio -> {
            calls.add("service.find(" + servicio + ")");
            return paymentService;
        };
        AccountRepository accounts = (cuenta, tipoCuenta) -> {
            calls.add("account.find(" + cuenta + "," + tipoCuenta + ")");
            return account;
        };
        DebitGateway gateway = (cuenta, tipoCuenta, valor, referencia) -> {
            calls.add("debit:" + referencia);
            debits.add(new DebitCall(cuenta, tipoCuenta, valor, referencia));
            if (debits.size() == failDebitCall) {
                throw new IllegalStateException("debit rejected");
            }
            return 500 + debits.size();
        };
        return new PayOrderService(orders, tariffs, services, accounts, gateway);
    }

    private PayOrderRequest req(String servicio, String tipo, String valor, String canal) {
        return new PayOrderRequest(100, 1, servicio, tipo, "1234567890", new BigDecimal(valor), canal, FECHA);
    }

    private PayOrderResponse run(PayOrderRequest request) {
        return service().execute(request);
    }

    private BusinessError rejected(PayOrderRequest request) {
        Throwable t = catchThrowable(() -> service().execute(request));
        assertThat(t).isInstanceOf(BusinessError.class);
        return (BusinessError) t;
    }

    private void assertError(BusinessError e, String code, String legacy, String message) {
        assertThat(e.code()).isEqualTo(code);
        assertThat(e.legacyCode()).isEqualTo(legacy);
        assertThat(e.getMessage()).isEqualTo(message);
    }

    private static CompanyTariff ctariff(String valor, String separada) {
        return new CompanyTariff(1, "AGUA", valor == null ? null : new BigDecimal(valor), separada);
    }

    private static Account acct(String tipo, String saldo) {
        return new Account("1234567890", tipo, saldo == null ? null : new BigDecimal(saldo));
    }

