package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.CompanyTariff;
import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.model.PaymentService;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.CompanyTariffRepository;
import com.bank.payments.domain.port.DebitGateway;
import com.bank.payments.domain.port.OrderRepository;
import com.bank.payments.domain.port.ServiceRepository;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Optional;

/** Use case PayOrder (legacy dbo.sp_pago_orden). */
public class PayOrderService {

    private static final BigDecimal OVERDRAFT_MARGIN = new BigDecimal("100.00");

    private final OrderRepository orderRepository;
    private final CompanyTariffRepository companyTariffRepository;
    private final ServiceRepository serviceRepository;
    private final AccountRepository accountRepository;
    private final DebitGateway debitGateway;

    public PayOrderService(OrderRepository orderRepository,
                           CompanyTariffRepository companyTariffRepository,
                           ServiceRepository serviceRepository,
                           AccountRepository accountRepository,
                           DebitGateway debitGateway) {
        this.orderRepository = orderRepository;
        this.companyTariffRepository = companyTariffRepository;
        this.serviceRepository = serviceRepository;
        this.accountRepository = accountRepository;
        this.debitGateway = debitGateway;
    }

    /** SQL-like equality: false when either side is NULL; trailing spaces are ignored. */
    private static boolean eq(String value, String literal) {
        if (value == null) {
            return false;
        }
        return rtrim(value).equals(literal);
    }

    private static String rtrim(String s) {
        int end = s.length();
        while (end > 0 && s.charAt(end - 1) == ' ') {
            end--;
        }
        return s.substring(0, end);
    }

    public PayOrderResponse execute(PayOrderRequest request) {
        String tipoCuenta = request.tipoCuenta();
        String canal = request.canal() == null ? "WEB" : request.canal();

        // RULE-001: NOT IN with NULL is unknown, so it does not reject
        if (tipoCuenta != null
                && !(eq(tipoCuenta, "CTE") || eq(tipoCuenta, "AHO") || eq(tipoCuenta, "VIR"))) {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        }

        // RULE-003 / RULE-002
        Optional<PaymentOrder> order = orderRepository.findByNumberAndCompany(request.orden(), request.empresa());
        if (order.isEmpty()) {
            throw new BusinessError("ORDER_NOT_FOUND", "50002", "ORDEN NO EXISTE");
        }
        String estado = order.get().ordEstado();
        // NULL <> 'P' is unknown: does not reject
        if (estado != null && !eq(estado, "P")) {
            throw new BusinessError("ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
        }

        // RULE-004
        BigDecimal tarifa = null;
        String separada = null;
        Optional<CompanyTariff> companyTariff =
                companyTariffRepository.findByCompanyAndService(request.empresa(), request.servicio());
        if (companyTariff.isPresent()) {
            tarifa = companyTariff.get().tarValor();
            separada = companyTariff.get().tarSeparada();
        } else {
            Optional<PaymentService> paymentService = serviceRepository.findByCode(request.servicio());
            if (paymentService.isPresent()) {
                tarifa = paymentService.get().srvTarifa();
                separada = "N";
            }
        }
        if (tarifa == null) {
            tarifa = BigDecimal.ZERO;
        }

        // RULE-005
        BigDecimal comision;
        if (eq(canal, "WEB")) {
            comision = tarifa.divide(new BigDecimal("2")).setScale(2, RoundingMode.HALF_UP);
        } else {
            comision = tarifa;
        }
        if (eq(request.servicio(), "NOMINA")) {
            comision = BigDecimal.ZERO;
        }
        comision = comision.setScale(4, RoundingMode.HALF_UP);

        // RULE-006
        BigDecimal total;
        if (eq(separada, "S")) {
            total = request.valor();
        } else {
            total = request.valor().add(comision);
        }

        // RULE-007: unknown balance (no row or NULL) does not reject
        Optional<Account> account = accountRepository.findByNumberAndType(request.cuenta(), tipoCuenta);
        BigDecimal saldo = account.isPresent() ? account.get().ctaSaldo() : null;
        if (saldo != null && tipoCuenta != null && total != null) {
            boolean insufficient;
            if (eq(tipoCuenta, "VIR")) {
                insufficient = saldo.compareTo(total) < 0;
            } else {
                insufficient = saldo.add(OVERDRAFT_MARGIN).compareTo(total) < 0;
            }
            if (insufficient) {
                throw new BusinessError("INSUFFICIENT_FUNDS", "50004", "FONDOS INSUFICIENTES");
            }
        }

        // RULE-008
        Integer movimiento;
        try {
            movimiento = debitGateway.debit(request.cuenta(), tipoCuenta, total, "PAGO ORDEN");
        } catch (RuntimeException e) {
            throw new BusinessError("DEBIT_FAILED", "50005", "ERROR EN DEBITO");
        }

        // RULE-009 / RULE-010
        if (eq(separada, "S") && comision.compareTo(BigDecimal.ZERO) > 0) {
            try {
                debitGateway.debit(request.cuenta(), tipoCuenta, comision, "COMISION PAGO");
            } catch (RuntimeException e) {
                throw new BusinessError("COMMISSION_FAILED", "50006", "ERROR EN COMISION");
            }
        }

        // RULE-011 / RULE-012
        int rows;
        try {
            rows = orderRepository.markPaid(request.orden(), request.empresa(), request.fechaProceso(), comision);
        } catch (RuntimeException e) {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }
        if (rows == 0) {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        // RULE-013
        return new PayOrderResponse(movimiento, "PAGO REALIZADO");
    }
}
